from pathlib import Path
import pandas as pd,json,hashlib,re,numpy as np
H=Path(__file__).resolve().parent

def main():
 base=pd.read_parquet(H/'all1767_native2021_geography_gaps_source_frame.parquet');a=pd.read_parquet(H/'dated_primary_and_geometry_validated_A_candidates_v2.parquet');b=pd.read_parquet(H/'B_v2_dated_exact_parent_source_assertions.parquet');c=pd.read_parquet(H/'all_usercode_only_complement_and_B_source_nodes.parquet');codes=set(base.native_np_oktmo11);extra=[]
 for x in c[c.user_code_only_complement].itertuples():
  t=json.loads(x.tags_json)
  for k in ['ref:oktmo','oktmo','oktmo:user']:
   if str(t.get(k,'')).strip() in codes:extra.append({'osm_type':x.osm_type,'osm_id':x.osm_id,'code':str(t[k]).strip(),'key':k,'tags_json':x.tags_json})
 assert not extra
 cb=c[c.B_source_node_validation].set_index('osm_id');check=[]
 for z in b[b.candidate_status.eq('B_dated_exact_parent_candidate')].itertuples():
  q=cb.loc[z.source_osm_node_id];same=q.osm_version==z.source_version and q.tags_json==z.source_tags_json and q.lat==z.source_lat and q.lon==z.source_lon and q.visible and not q.deleted;t=json.loads(q.tags_json);text=' '.join(str(t.get(k,'')) for k in ['note','fixme','description','source']).casefold();unc=any(x in text for x in ['approx','примерн','уточн','position uncertain','incorrect position']);check.append({'id':z.id,'node':z.source_osm_node_id,'actual_source_same_version_tags_coords':bool(same),'actual_visible':bool(q.visible),'actual_deleted':bool(q.deleted),'explicit_position_uncertainty':unc});assert same and not unc
 pd.DataFrame(check).to_parquet(H/'B21_actual_source_visibility_and_quality_readback.parquet',index=False)
 av=a[a.candidate_status.str.startswith(('A1_validated','A2_validated'))].copy();av['source_candidate_class']=av.candidate_status.str[:2];bv=b[b.candidate_status.eq('B_dated_exact_parent_candidate')&~b.id.isin(av.id)].copy();bv['source_candidate_class']='B2';bv=bv.rename(columns={'population2021':'population_2021','native_parent8':'native_source_parent8'});cols=['id','name','population_2021','native_np_oktmo11','native_source_parent8','source_osm_node_id','source_lat','source_lon','source_version','source_object_timestamp','source_tags_json','source_candidate_class'];cand=pd.concat([av[cols],bv[cols]],ignore_index=True);assert cand.id.is_unique and cand.source_osm_node_id.is_unique and np.isfinite(cand.source_lat).all() and np.isfinite(cand.source_lon).all();cand['coordinate_measurement_date_unknown']=True;cand['coordinate_precision_calibrated']=False;cand['source_snapshot_utc']='2021-01-01T21:42:03Z';cand['axis_adopted']=False;cand['independent_admission_status']='PENDING';cand.to_parquet(H/'all479_finite_source_coordinate_candidates.parquet',index=False)
 out=base.merge(cand[['id','source_candidate_class','source_osm_node_id','source_lat','source_lon']],on='id',how='left',validate='one_to_one');out['source_candidate_available']=out.source_candidate_class.notna();out['axis_adopted']=False;out['recovery_status']='unknown_no_validated_source_candidate';out.loc[out.source_candidate_available,'recovery_status']='finite_source_candidate_pending_independent_admission';out.loc[out.existing_source_snap_over10km,'recovery_status']='existing_over10km_unchanged';out.to_parquet(H/'all1767_finite_recovery_unknown_ledger.parquet',index=False)
 r={'status':'FINITE_SOURCE_COORDINATE_PROPOSAL_PENDING_INDEPENDENT_ADMISSION','candidate_NPs':len(cand),'by_source_class':cand.source_candidate_class.value_counts().to_dict(),'candidate_positive_NPs':int(cand.population_2021.gt(0).sum()),'candidate_population2021':float(cand.population_2021.sum()),'all_candidates_previously_coordinate_missing':bool(out.loc[out.source_candidate_available,'coordinate_missing'].all()),'remaining_coordinate_missing_NPs':int((out.coordinate_missing&~out.source_candidate_available).sum()),'remaining_coordinate_missing_population2021':float(out.loc[out.coordinate_missing&~out.source_candidate_available,'population_2021'].sum()),'existing_over10km_unchanged_NPs':int(out.existing_source_snap_over10km.sum()),'all_source_usercode_complement_has_no_target_native11_conflicts':True,'B21_actual_snapshot_metadata_checks_all_pass':True,'source_coordinate_measurement_date_unknown':True,'no_axis_or_graph_or_model_changes':True,'sha256':{f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in [H/'all479_finite_source_coordinate_candidates.parquet',H/'all1767_finite_recovery_unknown_ledger.parquet',H/'dated_primary_and_geometry_validated_A_candidates_v2.parquet',H/'B_v2_dated_exact_parent_source_assertions.parquet']}};(H/'finite_source_candidate_proposal_receipt.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');print(json.dumps(r,ensure_ascii=False))
if __name__=='__main__':main()
